-- Owner approval, 22 October 2026 (#92): apply the Sprint 11 library visitor-fact proposals.
-- 94 public libraries within 10 km of W3 9LN: an official website for each, plus opening hours for 29.
-- Generated from artefacts/data/sprint11-library-review.json by a one-off script; do not edit by hand.
-- Run AFTER supabase/migrations/20261019002054_sprint11_visitor_facts.sql (it lets reviews edit hours).
-- Each fact goes through dadspace_review_apply_v2 as an audited edit by the owner, so it is review-locked
-- against importers and shows its source on the venue page. The run stops if any edited field has
-- changed since the 19 Oct snapshot (checked equal on 22 Oct) or any library is no longer public.
begin;
do $$
declare n int; fp text;
begin
  select count(*) filter (where public_visible), md5(string_agg(id::text||'|'||coalesce(website,'')||'|'||coalesce(opening_hours,'')||'|'||coalesce(access,'')||'|'||coalesce(fee,''), ',' order by id::text collate "C"))
